ui.css:
.panel { background-color: #8f5c34; background-image: linear-gradient(#efe4cc,#efe4cc) 5px 5px/3px 3px no-repeat, linear-gradient(#efe4cc,#efe4cc) calc(100% - 8px) 5px/3px 3px no-repeat, linear-gradient(#efe4cc,#efe4cc) 5px calc(100% - 8px)/3px 3px no-repeat, linear-gradient(#efe4cc,#efe4cc) calc(100% - 8px) calc(100% - 8px)/3px 3px no-repeat, repeating-linear-gradient(180deg, rgba(0,0,0,0) 0 5px, rgba(58,30,16,.38) 5px 6px, rgba(0,0,0,0) 6px 11px, rgba(255,214,150,.14) 11px 12px, rgba(0,0,0,0) 12px 17px, rgba(58,30,16,.22) 17px 18px); border: 3px solid #2b170f; box-shadow: inset 3px 3px 0 #b97f4b, inset -3px -3px 0 #5e3820, 0 4px 0 rgba(26,12,6,.6); color: #fff3d6; font-family: 'Pixelify Sans', monospace; }
.bar { width: 220px; height: 22px; border: 3px solid #2b170f; background: #3a1c18; box-shadow: inset 0 3px 0 #200e0c, 0 3px 0 #c58a54; }
.bar-red { height: 100%; background: linear-gradient(180deg, #ffa58a 0 3px, #ee4f36 3px 9px, #c0302c 9px 13px, #8e1f2a 13px); }
.bar-amber { background: linear-gradient(180deg, #fff0a0 0 3px, #ffc94a 3px 8px, #f19434 8px 12px, #c8621f 12px); }
.hud-num { font: 700 24px 'Silkscreen', monospace; color: #fff3d6; text-shadow: 2px 0 #2b170f, -2px 0 #2b170f, 0 2px #2b170f, 0 -2px #2b170f, 2px 2px #2b170f, -2px 2px #2b170f, 2px -2px #2b170f, -2px -2px #2b170f, 0 4px #2b170f; }
.hud-icon { width: 48px; height: 48px; image-rendering: pixelated; }
